    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        # These color sequences have period 7 (the border colors are also intact).
        known = [(c, v) for c, v in enumerate(grid[r]) if v != 0]
        for c in range(w):
            if grid[r][c] != 0:
                continue
            cand = [(abs(k-c), v) for k, v in known if (k-c) % 7 == 0]
            if cand:
                out[r][c] = min(cand)[1]
            else:
                # Adjacent row same-column value normally provides the phase.
                for d in range(1, h):
                    for q in (r-d, r+d):
                        if 0 <= q < h and grid[q][c] != 0:
                            out[r][c] = grid[q][c]
                            break
                    if out[r][c] != 0:
                        break
    return out
